package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SamlIdpCertVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property saml idp cert of tenant login provider ")
  void test_saml_idp_cert_v_o_builder() {
    Assertions.assertFalse(SamlIdpCertVO.nullValue().getSamlIdpCert().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SamlIdpCertVO.tryFrom(null).getSamlIdpCert().isPresent(),
        "With a null value, no present result");
    Assertions.assertThrows(ConstraintException.class,
        () -> SamlIdpCertVO.tryFrom(Integer.valueOf(1)));
    Assertions.assertEquals("file_1", SamlIdpCertVO.from("file_1").getSamlIdpCert().orElse(null));
    Assertions.assertEquals("[" + "file_1" + "]", SamlIdpCertVO.fromTemporal("file_1").toString());
    Assertions.assertFalse(SamlIdpCertVO.from("file_1").isSamlIdpCertTemporal());
    Assertions.assertTrue(SamlIdpCertVO.fromTemporal("file_1").isSamlIdpCertTemporal());
    Assertions.assertEquals("[" + "file_1" + "]", SamlIdpCertVO.from("file_1").toString());
    Assertions.assertFalse(SamlIdpCertVO.tryFrom("1").isSamlIdpCertTemporal());
    Assertions.assertTrue(SamlIdpCertVO.tryFrom("temp://1").isSamlIdpCertTemporal());
  }
}
